('direitos-cuidados-consumidor','Direitos e cuidados do consumidor',30),('prevencao-golpes','Prevenção de golpes',40),
('planejamento-financeiro','Planejamento financeiro',50),('autoridade-marca','Autoridade da marca',60),
('conteudo-institucional','Conteúdo institucional',70),('diagnostico-financeiro','Diagnóstico financeiro',80),
('organizacao-priorizacao-dividas','Organização e priorização de dívidas',90);
insert into public.content_studio_networks(slug,label) values ('instagram','Instagram'),('facebook','Facebook'),('tiktok','TikTok');
insert into public.content_studio_formats(slug,label,width,height) values
